using System;
using System.Collections.Generic;
using System.Drawing;
using System.Globalization;
using System.Linq;
using System.Windows.Forms;
using DrawingPoint=System.Drawing.Point;

namespace ExperimentMonitor {
    public sealed class ChartSample {
        public DateTime Utc { get; set; }
        public double? Value { get; set; }
        public string Quality { get; set; }
    }

    /// <summary>Shared realtime and history chart. Stores exact samples supplied by caller; drawing never mutates values.</summary>
    public sealed class ExperimentChart : Control {
        readonly Dictionary<string,List<ChartSample>> data=new Dictionary<string,List<ChartSample>>();
        readonly Dictionary<string,bool> visible=new Dictionary<string,bool>();
        readonly Color[] colors={Color.FromArgb(54,112,220),Color.FromArgb(0,153,132),Color.FromArgb(232,145,38),Color.FromArgb(167,78,184),Color.FromArgb(220,80,90),Color.FromArgb(48,155,196),Color.FromArgb(130,142,50),Color.FromArgb(181,118,27)};
        readonly ToolTip tooltip=new ToolTip { InitialDelay=0,ReshowDelay=0,AutoPopDelay=12000,ShowAlways=true };
        string[] selected=new string[0]; bool fixedRange,dragging,dragMoved,hasQueryRange,dragWasFixed,dragWasFollow; DateTime rangeStart,rangeEnd,dragStartTime,dragEndTime,queryStart,queryEnd; DrawingPoint dragStart; int WindowMinutes=30; bool followLatest=true; readonly List<Rectangle> plotRects=new List<Rectangle>();
        public event Action<string,bool> LegendVisibilityChanged;
        public event Action<string,DateTime> ExactSampleRequested;
        public bool RequestExactSamples { get; set; }
        public int RequiredHeight { get { return Math.Max(210,selected.Select(n=>PointCatalog.Get(n).Unit??"").Distinct().Count()*205); } }
        public ExperimentChart() { DoubleBuffered=true;BackColor=Color.White;Font=new Font("Microsoft YaHei UI",9);MinimumSize=new Size(280,170);SetStyle(ControlStyles.ResizeRedraw|ControlStyles.OptimizedDoubleBuffer,true); }
        public void SelectPoints(IEnumerable<string> names) { selected=(names??Enumerable.Empty<string>()).Distinct().ToArray();foreach(string n in selected)if(!visible.ContainsKey(n))visible[n]=true;ConstrainRangeToData();Invalidate(); }
        public void Clear() { data.Clear();exactSamples.Clear();exactTargets.Clear();fixedRange=false;hasQueryRange=false;Invalidate(); }
        public void SetWindowMinutes(int minutes) { WindowMinutes=Math.Max(1,minutes);followLatest=true;fixedRange=false;hasQueryRange=false;Invalidate(); }
        public void SetTimeRange(DateTime fromUtc,DateTime toUtc,bool follow) { if(toUtc<=fromUtc)throw new ArgumentException("趋势结束时间必须晚于开始时间");rangeStart=fromUtc.ToUniversalTime();rangeEnd=toUtc.ToUniversalTime();followLatest=follow;fixedRange=!follow;if(follow){hasQueryRange=false;}else{queryStart=rangeStart;queryEnd=rangeEnd;hasQueryRange=true;}Invalidate(); }
        public void SetSeriesData(IDictionary<string,IEnumerable<ChartSample>> series) { bool requestedRange=fixedRange;data.Clear();exactSamples.Clear();exactTargets.Clear();if(series!=null)foreach(var pair in series)data[pair.Key]=(pair.Value??Enumerable.Empty<ChartSample>()).OrderBy(x=>x.Utc).ToList();fixedRange=requestedRange&&rangeEnd>rangeStart;if(fixedRange)ConstrainRangeToData();Invalidate(); }
        public void Add(Observation o) { if(o==null)return;List<ChartSample> list;if(!data.TryGetValue(o.Point,out list)){list=new List<ChartSample>();data[o.Point]=list;}list.Add(new ChartSample{Utc=o.Utc.ToUniversalTime(),Value=o.Quality=="good"?o.Number:null,Quality=o.Quality});if(list.Count>12000)list.RemoveRange(0,list.Count-12000);ConstrainRangeToData();if(followLatest&&!fixedRange)Invalidate(); }
        Rectangle PlotAt(DrawingPoint p) { foreach(Rectangle rect in plotRects)if(rect.Contains(p))return rect;return Rectangle.Empty; }
        protected override void OnMouseWheel(MouseEventArgs e) {
            HandledMouseEventArgs handled=e as HandledMouseEventArgs;
            if((ModifierKeys&Keys.Control)==Keys.Control){Rectangle rect=PlotAt(e.Location);if(rect.Width==0)rect=new Rectangle(0,0,Width,Height);ZoomAt(e.Location,rect,e.Delta);Invalidate();if(handled!=null)handled.Handled=true;base.OnMouseWheel(e);return;}
            base.OnMouseWheel(e);
        }
        string[] ZoomSeries(){string[] ids=selected.Where(data.ContainsKey).ToArray();return ids.Length>0?ids:data.Keys.ToArray();}
        void ZoomAt(DrawingPoint point,Rectangle rect,int delta){DateTime a,b;GetRange(out a,out b);double old=(b-a).TotalSeconds;if(old<=0)return;double next=Math.Max(10,Math.Min(86400*90,old*(delta>0?.75:1.33)));double anchor=Math.Max(0,Math.Min(1,(double)(point.X-rect.Left)/Math.Max(1,rect.Width)));DateTime proposed=a.AddSeconds((old-next)*anchor);DateTime first=DateTime.MaxValue,last=DateTime.MinValue;foreach(string id in ZoomSeries()){List<ChartSample> values;if(data.TryGetValue(id,out values)&&values.Count>0){DateTime lo=values.Min(x=>x.Utc),hi=values.Max(x=>x.Utc);if(lo<first)first=lo;if(hi>last)last=hi;}}if(first==DateTime.MaxValue||last<=first)return;double span=(last-first).TotalSeconds;if(span<10)return;next=Math.Min(next,span);double maxOffset=Math.Max(0,span-next);double offset=(proposed-first).TotalSeconds;offset=Math.Max(0,Math.Min(maxOffset,offset));rangeStart=first.AddSeconds(offset);rangeEnd=rangeStart.AddSeconds(next);fixedRange=true;followLatest=false;}
        void ConstrainRangeToData(){if(!fixedRange)return;DateTime first=DateTime.MaxValue,last=DateTime.MinValue;foreach(string id in ZoomSeries()){List<ChartSample> values;if(data.TryGetValue(id,out values)&&values.Count>0){DateTime lo=values.Min(x=>x.Utc),hi=values.Max(x=>x.Utc);if(lo<first)first=lo;if(hi>last)last=hi;}}if(first==DateTime.MaxValue||last<=first){RestoreFullRange();return;}double span=(last-first).TotalSeconds,window=Math.Max(10,(rangeEnd-rangeStart).TotalSeconds);if(span<10){RestoreFullRange();return;}window=Math.Min(window,span);double offset=(rangeStart-first).TotalSeconds;offset=Math.Max(0,Math.Min(span-window,offset));rangeStart=first.AddSeconds(offset);rangeEnd=rangeStart.AddSeconds(window);}
        internal DateTime RangeStartForTests{get{DateTime a,b;GetRange(out a,out b);return a;}}
        internal DateTime RangeEndForTests{get{DateTime a,b;GetRange(out a,out b);return b;}}
        internal bool FixedRangeForTests{get{return fixedRange;}}
        protected override void OnMouseDown(MouseEventArgs e) { Rectangle rect=PlotAt(e.Location);if(e.Button==MouseButtons.Left&&rect.Width>0){dragging=true;dragMoved=false;dragStart=e.Location;GetRange(out rangeStart,out rangeEnd);dragStartTime=rangeStart;dragEndTime=rangeEnd;dragWasFixed=fixedRange;dragWasFollow=followLatest;dragPlot=rect;Capture=true;}base.OnMouseDown(e); }
        Rectangle dragPlot;
        protected override void OnMouseMove(MouseEventArgs e) { if(dragging){double seconds=(rangeEnd-rangeStart).TotalSeconds;double shift=-(e.X-dragStart.X)*seconds/Math.Max(1,dragPlot.Width);rangeStart=dragStartTime.AddSeconds(shift);rangeEnd=rangeStart.AddSeconds(seconds);if(Math.Abs(e.X-dragStart.X)>2||Math.Abs(e.Y-dragStart.Y)>2)dragMoved=true;fixedRange=true;followLatest=false;Invalidate();}else{lastPointer=e.Location;ShowNearest(e.Location);RequestExactAt(e.Location);}base.OnMouseMove(e); }
        DateTime lastClickUtc;DrawingPoint lastClickPos;
        protected override void OnMouseUp(MouseEventArgs e) { if(dragging){dragging=false;Capture=false;if(dragMoved)ConstrainRangeToData();else{rangeStart=dragStartTime;rangeEnd=dragEndTime;fixedRange=dragWasFixed;followLatest=dragWasFollow;}dragMoved=false;}if(e.Button==MouseButtons.Left){DateTime now=DateTime.UtcNow;bool near=Math.Abs(e.X-lastClickPos.X)<=6&&Math.Abs(e.Y-lastClickPos.Y)<=6;if((now-lastClickUtc).TotalMilliseconds<=650&&near){lastClickUtc=DateTime.MinValue;RestoreFullRange();}else{lastClickUtc=now;lastClickPos=e.Location;}}base.OnMouseUp(e); }
        public void RestoreFullRange(){if(hasQueryRange){rangeStart=queryStart;rangeEnd=queryEnd;fixedRange=true;followLatest=false;}else{followLatest=true;fixedRange=false;}Invalidate();}
        protected override void OnDoubleClick(EventArgs e) { RestoreFullRange();base.OnDoubleClick(e); }
        string hoveredId;DateTime hoveredTarget,lastExactRequest;DrawingPoint lastPointer;readonly Dictionary<string,ChartSample> exactSamples=new Dictionary<string,ChartSample>();readonly Dictionary<string,DateTime> exactTargets=new Dictionary<string,DateTime>();
        public void SetExactSample(string point,ChartSample sample,DateTime target){if(point!=hoveredId||Math.Abs((target.ToUniversalTime()-hoveredTarget).TotalSeconds)>2)return;exactSamples[point]=sample;exactTargets[point]=target.ToUniversalTime();ShowNearest(lastPointer);}
        void RequestExactAt(DrawingPoint p){if(!RequestExactSamples)return;Rectangle rect=PlotAt(p);if(rect.Width==0)return;DateTime a,b;GetRange(out a,out b);DateTime target=a.AddSeconds((double)(p.X-rect.Left)/Math.Max(1,rect.Width)*(b-a).TotalSeconds);string unit=UnitForRect(rect),best=null;double bestDistance=double.MaxValue;foreach(string id in selected){if((PointCatalog.Get(id).Unit??"")!=unit)continue;List<ChartSample> values;if(!data.TryGetValue(id,out values))continue;ChartSample nearest=values.Where(x=>x.Value.HasValue).OrderBy(x=>Math.Abs((x.Utc-target).TotalSeconds)).FirstOrDefault();if(nearest!=null){double distance=Math.Abs((nearest.Utc-target).TotalSeconds);if(distance<bestDistance){best=id;bestDistance=distance;}}}if(best==null)return;if(lastExactRequest!=DateTime.MinValue&&(DateTime.UtcNow-lastExactRequest).TotalMilliseconds<650&&hoveredId==best&&Math.Abs((target-hoveredTarget).TotalSeconds)<3)return;hoveredId=best;hoveredTarget=target;lastExactRequest=DateTime.UtcNow;Action<string,DateTime> handler=ExactSampleRequested;if(handler!=null)handler(best,target);}
        void ShowNearest(DrawingPoint p) { Rectangle rect=PlotAt(p);if(rect.Width==0){tooltip.Hide(this);return;}DateTime a,b;GetRange(out a,out b);ChartSample best=null;string bestId=null;double dist=double.MaxValue;foreach(string id in selected){if((PointCatalog.Get(id).Unit??"")!=UnitForRect(rect))continue;bool shown;if(visible.TryGetValue(id,out shown)&&!shown)continue;List<ChartSample> list;if(!data.TryGetValue(id,out list))continue;foreach(ChartSample sample in list){double x=rect.Left+(sample.Utc-a).TotalSeconds/Math.Max(.001,(b-a).TotalSeconds)*rect.Width;double d=Math.Abs(x-p.X);if(d<dist&&d<16){dist=d;best=sample;bestId=id;}}}if(best==null){tooltip.Hide(this);return;}ChartSample exact;DateTime exactTarget;if(RequestExactSamples&&bestId==hoveredId&&exactSamples.TryGetValue(bestId,out exact)&&exactTargets.TryGetValue(bestId,out exactTarget)&&Math.Abs((exactTarget-hoveredTarget).TotalSeconds)<=2&&Math.Abs((exact.Utc-hoveredTarget).TotalSeconds)<Math.Max(30,WindowMinutes*60.0/Math.Max(1,rect.Width)*16))best=exact;string value=best.Value.HasValue?best.Value.Value.ToString("G9",CultureInfo.InvariantCulture):"无有效数值（"+(best.Quality??"缺失")+")";tooltip.Show(PointCatalog.Get(bestId).Label+" · "+bestId+"\r\n"+best.Utc.ToLocalTime().ToString("yyyy-MM-dd HH:mm:ss.fff",CultureInfo.InvariantCulture)+"\r\n"+value+" "+PointCatalog.Get(bestId).Unit,this,new DrawingPoint(p.X+14,p.Y+18),5000); }
        readonly Dictionary<Rectangle,string> axisUnits=new Dictionary<Rectangle,string>();
        string UnitForRect(Rectangle rect){string unit;return axisUnits.TryGetValue(rect,out unit)?unit:"";}
        void GetRange(out DateTime from,out DateTime to) { if(fixedRange){from=rangeStart;to=rangeEnd;return;}var all=selected.Where(data.ContainsKey).SelectMany(n=>data[n]).ToArray();if(all.Length==0){to=DateTime.UtcNow;from=to.AddMinutes(-WindowMinutes);return;}to=all.Max(x=>x.Utc);DateTime earliest=all.Min(x=>x.Utc);from=to.AddMinutes(-WindowMinutes);if(earliest>from)from=earliest;if(from==to)from=to.AddSeconds(-Math.Max(1,WindowMinutes*60)); }
