                using(Pen gridPen=new Pen(UiTheme.Line))for(int l=0;l<=4;l++)g.DrawLine(gridPen,emptyRect.Left,emptyRect.Top+emptyRect.Height*l/4,emptyRect.Right,emptyRect.Top+emptyRect.Height*l/4);
